// Spec-style helpers (for documentation / reasoning):
//
// is_subrange_at(main, sub, k) is true iff:
//   0 <= k <= main.len() - sub.len()  AND  main[k .. k+sub.len()] == sub
//
// matches_at(main, sub, start) is true under the precondition:
//   start + sub.len() <= main.len()
// and means element-wise equality at that offset.

fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Precondition (as described): start + sub.len() <= main.len()
    // We'll keep this function total by returning false if violated.
    if start > main.len() || sub.len() > main.len() - start {
        return false;
    }

    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // Empty subarray always matches.
    if sub.is_empty() {
        return true;
    }
    // If sub longer than main, can't match.
    if sub.len() > main.len() {
        return false;
    }

    // Try every valid start position k where sub could fit.
    let last_start = main.len() - sub.len();
    for k in 0..=last_start {
        if check_match_at(main, sub, k) {
            return true;
        }
    }
    false
}

